using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OrcaFacil.Application.Abstractions;using OrcaFacil.Application.Saas.Modules;using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.AccountAdmin.Modules;[Authorize(Policy="AccountAdmin")]public sealed class IndexModel(OrcaFacilDbContext db,ICurrentAccountService current,IAccountModuleSubscriptionService subscriptions):PageModel{public IReadOnlyList<Row>Modules{get;private set;}=[];public async Task<IActionResult>OnGetAsync(CancellationToken ct){if(current.AccountId is not Guid account)return Forbid();Modules=await db.SaasModules.AsNoTracking().Where(x=>x.IsActive&&x.IsPublic&&!x.IsDeleted).GroupJoin(db.AccountModuleSubscriptions.AsNoTracking().Where(x=>x.AccountId==account&&!x.IsDeleted),m=>m.Id,s=>s.ModuleId,(m,s)=>new{m,s=s.FirstOrDefault()}).OrderBy(x=>x.m.DisplayOrder).Select(x=>new Row(x.m.Code,x.m.DisplayName,x.m.Description,x.m.BaseMonthlyPrice,x.m.BaseAnnualPrice,x.s==null?"Disponível":x.s.Status.ToString(),x.s==null)).ToListAsync(ct);return Page();}public async Task<IActionResult>OnPostAsync(string moduleCode,string billingPeriod,CancellationToken ct){if(current.AccountId is not Guid account)return Forbid();await subscriptions.RequestAsync(account,moduleCode,billingPeriod,current.UserId,ct);return RedirectToPage();}public sealed record Row(string Code,string Name,string Description,decimal Monthly,decimal Annual,string Status,bool CanRequest);}
